package ingest

import "testing"

func TestGSRWitness(t *testing.T) {
	got := containsAnyWord("vice-president of product", []string{"vice-president"})
	if got != true {
		t.Fatalf("containsAnyWord(%q, %v) = %v, want %v", "vice-president of product", []string{"vice-president"}, got, true)
	}
}
